package ma.translogix.model;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * One fuel voucher (bon de gazole) issued for a mission in progress.
 * The reference BON-xxxx is generated by BonCarburantService; the truck and the driver come from the mission.
 */
public class BonCarburant {
    private Long id;
    private String reference;
    private Long missionId;
    private Long vehiculeId;
    private Long chauffeurId;
    private String station;
    private BigDecimal litres;
    private BigDecimal montant;
    private LocalDate date;
    private StatutBonCarburant statut = StatutBonCarburant.VALIDE;

    public BonCarburant() {
    }

    public BonCarburant(Long id, String reference, Long missionId, Long vehiculeId, Long chauffeurId,
                        String station, BigDecimal litres, BigDecimal montant, LocalDate date,
                        StatutBonCarburant statut) {
        this.id = id;
        this.reference = reference;
        this.missionId = missionId;
        this.vehiculeId = vehiculeId;
        this.chauffeurId = chauffeurId;
        this.station = station;
        this.litres = litres;
        this.montant = montant;
        this.date = date;
        this.statut = statut;
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public String getReference() { return reference; }
    public void setReference(String reference) { this.reference = reference; }

    public Long getMissionId() { return missionId; }
    public void setMissionId(Long missionId) { this.missionId = missionId; }

    public Long getVehiculeId() { return vehiculeId; }
    public void setVehiculeId(Long vehiculeId) { this.vehiculeId = vehiculeId; }

    public Long getChauffeurId() { return chauffeurId; }
    public void setChauffeurId(Long chauffeurId) { this.chauffeurId = chauffeurId; }

    public String getStation() { return station; }
    public void setStation(String station) { this.station = station; }

    public BigDecimal getLitres() { return litres; }
    public void setLitres(BigDecimal litres) { this.litres = litres; }

    public BigDecimal getMontant() { return montant; }
    public void setMontant(BigDecimal montant) { this.montant = montant; }

    public LocalDate getDate() { return date; }
    public void setDate(LocalDate date) { this.date = date; }

    public StatutBonCarburant getStatut() { return statut; }
    public void setStatut(StatutBonCarburant statut) { this.statut = statut; }
}
